import{_ as t}from"./chunks/npu_3510_hw_arch_sync.DHjro_LS.js";import{_ as s}from"./chunks/atlas_a2_a3_architecture.QjujfbJW.js";import{_ as d,a as e}from"./chunks/intra_core_parallel_pipeline_execution_timing.BdSPSiwi.js";import{_ as a}from"./chunks/inter_core_sync_scenario_example.Cgh3NH_Y.js";import{_}from"./chunks/block_subblock_relationship_3510.Dld0RPG9.js";import{_ as o}from"./chunks/3510_sync_control_mode_diagram.tNcLb1Xz.js";import{_ as n,o as r,a as E,b as i}from"./app.B47EjQll.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"同步控制","link":"/api/SIMD-API/c_api/sync/sync"},{"text":"概述","link":"/api/SIMD-API/c_api/sync/overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/sync/overview.md","filePath":"api/SIMD-API/c_api/sync/overview.md","outlineHeaders":[{"level":2,"title":"同步控制概述","slug":"同步控制概述","link":"#同步控制概述"},{"level":3,"title":"同步类型与使用场景","slug":"同步类型与使用场景","link":"#同步类型与使用场景"},{"level":3,"title":"核内同步原理","slug":"核内同步原理","link":"#核内同步原理"},{"level":4,"title":"为什么需要核内同步","slug":"为什么需要核内同步","link":"#为什么需要核内同步"},{"level":4,"title":"硬件流水类型","slug":"硬件流水类型","link":"#硬件流水类型"},{"level":4,"title":"核内同步组合","slug":"核内同步组合","link":"#核内同步组合"},{"level":4,"title":"什么时候需要开发者手动插入同步","slug":"什么时候需要开发者手动插入同步","link":"#什么时候需要开发者手动插入同步"},{"level":3,"title":"核间同步原理","slug":"核间同步原理","link":"#核间同步原理"},{"level":4,"title":"核间同步控制模式","slug":"核间同步控制模式","link":"#核间同步控制模式"},{"level":2,"title":"API列表","slug":"API列表","link":"#API列表"},{"level":3,"title":"核内同步","slug":"核内同步","link":"#核内同步"},{"level":3,"title":"核间同步","slug":"核间同步","link":"#核间同步"}],"lastUpdated":1794017913000}'),P={name:"api/SIMD-API/c_api/sync/overview.md"};function I(p,c,l,y,h,b){return r(),E("div",null,[...c[0]||(c[0]=[i('<div><article class="markdown-body"><h1>概述</h1><h2 id="同步控制概述">同步控制概述<a class="header-anchor" href="#同步控制概述">​</a></h2><p>同步控制C API提供核内流水同步，以及核间、子核间的通知与等待接口。</p><h3 id="同步类型与使用场景">同步类型与使用场景<a class="header-anchor" href="#同步类型与使用场景">​</a></h3><p>在Ascend C编程中，同步用于约束AI Core内外不同执行单元的执行先后关系，确保后续指令在依赖的数据、状态或同步信号就绪后再继续执行。由于数据搬运、计算、不同核函数（Kernel）或不同AI Core之间可以并行，如果缺少必要的同步，后续执行单元可能读取到尚未写入完成的数据，或在前序任务未完成时提前执行，导致计算结果错误或执行行为不符合预期。</p><p>AI Core的同步，总共分成2类：<a href="#%E6%A0%B8%E5%86%85%E5%90%8C%E6%AD%A5%E5%8E%9F%E7%90%86">核内同步</a>、<a href="#%E6%A0%B8%E9%97%B4%E5%90%8C%E6%AD%A5%E5%8E%9F%E7%90%86">核间同步</a>。</p><p>以下内容展示两类同步的使用场景。</p><ul><li><p>核内同步用于约束同一核内不同硬件流水或同一硬件流水内指令的执行时序。</p><p>例如在AIV中，MTE2单元通过<code>PIPE_MTE2</code>将数据搬入片上存储后，Vector单元才可以通过<code>PIPE_V</code>读取该数据进行计算，此时需要插入<code>PIPE_MTE2</code>到<code>PIPE_V</code>的同步，使<code>PIPE_V</code>等待<code>PIPE_MTE2</code>的前序搬入完成。</p></li><li><p>核间同步用于约束不同核之间的执行时序，参与同步的对象可以是多个AI Core，也可以是同一AI Core内的AIC和AIV。</p><div data-filter="950"><p>如图1所示，针对<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本3510</a>，同一个AI Core内AIV通过<code>PIPE_MTE3</code>将数据从UB搬运到L1 Buffer后，AIC侧<code>PIPE_MTE1</code>才能将L1 Buffer中的数据搬入L0A Buffer和L0B Buffer并继续执行矩阵计算，此时需要让AIC等待AIV的数据搬运完成通知。</p><p>核内同步和核间同步的区别在于：核内同步解决同一核内部硬件流水之间的数据依赖，关注<code>PIPE_MTE2</code>、<code>PIPE_V</code>等流水的先后关系；核间同步解决不同核或不同逻辑核之间的进度依赖，关注AIC、AIV或多个AI Core之间的先后关系。</p><p><strong>图1</strong> <a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本3510</a>架构图</p><p><img src="'+t+'" alt></p></div></li></ul><h3 id="核内同步原理">核内同步原理<a class="header-anchor" href="#核内同步原理">​</a></h3><h4 id="为什么需要核内同步">为什么需要核内同步<a class="header-anchor" href="#为什么需要核内同步">​</a></h4><p>AI Core内部的执行单元（如MTE2搬运单元、Vector计算单元等）以异步并行的方式运行，在读写同一存储资源时可能存在数据依赖关系。为确保数据一致性及计算正确性，需通过同步控制协调操作时序。</p><div data-filter="950"><p>针对<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本3510</a>，硬件架构如图1所示，高亮部分展示了并行执行的计算单元和搬运单元。</p></div><div data-filter="A3,910b"><p>针对<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本2201</a>，硬件架构图如下，高亮部分展示了并行执行的计算单元和搬运单元。</p><p><strong>图2</strong> NPU架构版本2201架构图</p><p><img src="'+s+'" alt></p></div><p>下图示例描述了一个常见的Vector计算数据流：</p><ol><li>先通过DMA执行单元将数据从GM搬入到Local Memory；</li><li>进行计算；</li><li>然后再通过DMA执行单元将计算结果从Local Memory搬出到GM。</li></ol><p><strong>图3</strong> Vector计算数据流示意图</p><p><img src="'+d+'" alt></p><p>四个执行单元Scalar、Vector、DMA（MTE2）、DMA（MTE3）并行执行，若访问同一片Local Memory，需要同步机制来控制它们的访问时序：保证先搬入Local Memory后再计算，计算完成后再搬出。</p><p><strong>图4</strong> 核内并行流水执行时序示意图</p><p><img src="'+e+`" alt></p><h4 id="硬件流水类型">硬件流水类型<a class="header-anchor" href="#硬件流水类型">​</a></h4><p>AI Core内部并行的指令流水类型和解释如下所示：</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>不同的硬件架构，每一种硬件流水类型包含的具体流水会有所差异，详细介绍请参考<a href="../../../../guide/programming_guide/advanced_programming/hardware_implementation/hardware_implementation.html">硬件实现</a>章节。</p></div><p><strong>表1</strong> 指令流水类型和相关说明</p><table><thead><tr><th>流水类型</th><th>含义</th></tr></thead><tbody><tr><td><code>PIPE_S</code></td><td>标量流水，使用标量访存语句或标量计算接口访问GM、片上存储地址时为此流水</td></tr><tr><td><code>PIPE_V</code></td><td>矢量计算流水及部分硬件架构下的L0C Buffer-&gt;UB数据搬运流水</td></tr><tr><td><code>PIPE_M</code></td><td>矩阵计算流水</td></tr><tr><td><code>PIPE_MTE1</code></td><td>L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer数据搬运流水</td></tr><tr><td><code>PIPE_MTE2</code></td><td>GM-&gt;L1 Buffer、GM-&gt;UB等数据搬运流水</td></tr><tr><td><code>PIPE_MTE3</code></td><td>UB-&gt;GM等数据搬运流水</td></tr><tr><td><code>PIPE_FIX</code></td><td>L0C Buffer-&gt;GM、L0C Buffer-&gt;L1 Buffer等数据搬运流水</td></tr></tbody></table><p>此外，<code>PIPE_ALL</code>表示全部流水，用于需要等待所有流水前序指令完成的场景。</p><p>同步接口中<code>pipe_t</code>枚举类型的取值如下：<a id="硬件流水类型"></a></p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">typedef</span><span class="w"> </span><span class="k">enum</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">PIPE_S</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_V</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_M</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_MTE1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_MTE2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_MTE3</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">5</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_ALL</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">6</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_FIX</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">10</span>
<span class="p">}</span><span class="w"> </span><span class="n">pipe_t</span><span class="p">;</span>
</code></pre></div><h4 id="核内同步组合">核内同步组合<a class="header-anchor" href="#核内同步组合">​</a></h4><div data-filter="A3,910b"><p>以<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本2201</a>为例，该硬件架构下所有合法的核内同步组合如<a href="#aic_intra_core_sync_combinations">表2</a>和<a href="#aiv_intra_core_sync_combinations">表3</a>所示。其中，“不涉及”表示硬件层面不存在此种同步组合，“暂无应用场景”表示存在此种同步组合，但在实际开发场景中暂不需要使用。</p><p><a id="aic_intra_core_sync_combinations"></a></p><p><strong>表2</strong> AIC中所有合法的核内同步组合</p><table><thead><tr><th>源流水/目的流水</th><th><code>PIPE_S</code></th><th><code>PIPE_M</code></th><th><code>PIPE_MTE1</code></th><th><code>PIPE_MTE2</code></th><th><code>PIPE_MTE3</code></th><th><code>PIPE_FIX</code></th></tr></thead><tbody><tr><td><code>PIPE_S</code></td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td></tr><tr><td><code>PIPE_M</code></td><td>不涉及</td><td><code>asc_sync_pipe(PIPE_M)</code></td><td><code>asc_sync_notify(PIPE_M, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_M, PIPE_MTE1, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_M, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_M, PIPE_MTE2, EVENT_ID0)</code></td><td>不涉及</td><td><code>asc_sync_notify(PIPE_M, PIPE_FIX, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_M, PIPE_FIX, EVENT_ID0)</code></td></tr><tr><td><code>PIPE_MTE1</code></td><td>不涉及</td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_M, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_M, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE1)</code></td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_MTE3, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_FIX, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_FIX, EVENT_ID0)</code></td></tr><tr><td><code>PIPE_MTE2</code></td><td>不涉及</td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_M, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_M, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_MTE1, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE2)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code></td><td>暂无应用场景</td></tr><tr><td><code>PIPE_MTE3</code></td><td>不涉及</td><td>不涉及</td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_MTE1, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE3)</code></td><td>暂无应用场景</td></tr><tr><td><code>PIPE_FIX</code></td><td>不涉及</td><td><code>asc_sync_notify(PIPE_FIX, PIPE_M, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_FIX, PIPE_M, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_FIX, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_FIX, PIPE_MTE1, EVENT_ID0)</code></td><td>暂无应用场景</td><td>暂无应用场景</td><td><code>asc_sync_pipe(PIPE_FIX)</code></td></tr></tbody></table><p><a id="aiv_intra_core_sync_combinations"></a></p><p><strong>表3</strong> AIV中所有合法的核内同步组合</p><table><thead><tr><th>源流水/目的流水</th><th><code>PIPE_S</code></th><th><code>PIPE_V</code></th><th><code>PIPE_MTE2</code></th><th><code>PIPE_MTE3</code></th></tr></thead><tbody><tr><td><code>PIPE_S</code></td><td>不涉及</td><td><code>asc_sync_notify(PIPE_S, PIPE_V, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_S, PIPE_V, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_S, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_S, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_S, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_S, PIPE_MTE3, EVENT_ID0)</code></td></tr><tr><td><code>PIPE_V</code></td><td><code>asc_sync_notify(PIPE_V, PIPE_S, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_V, PIPE_S, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_V)</code></td><td><code>asc_sync_notify(PIPE_V, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_V, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_V, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_V, PIPE_MTE3, EVENT_ID0)</code></td></tr><tr><td><code>PIPE_MTE2</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_S, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_S, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_V, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_V, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE2)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code></td></tr><tr><td><code>PIPE_MTE3</code></td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_S, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_S, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_V, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_V, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE3)</code></td></tr></tbody></table></div><h4 id="什么时候需要开发者手动插入同步">什么时候需要开发者手动插入同步<a class="header-anchor" href="#什么时候需要开发者手动插入同步">​</a></h4><p>C API编程方式下所有的同步均需开发者手动管理。</p><h3 id="核间同步原理">核间同步原理<a class="header-anchor" href="#核间同步原理">​</a></h3><p>核间同步的使用场景通常是：一个核计算所依赖的数据，需要等待其他相关核的计算全部完成后才能获取。</p><p>以图5为例，AIC需要依赖AIV的<code>asc_reduce</code>计算结果。由于整体矢量较大，必须拆分为多个部分，由每个AIV分别完成部分计算。每个AIV将其部分计算结果通过原子累加写入GM。AIC必须读取所有AIV均完成累加后的最终结果，因此需要通过核间同步来保证AIC读取<code>asc_reduce</code>结果时的时序正确性。</p><p><strong>图5</strong> 核间同步业务场景示例图（AIC与AIV的比例为1：2）</p><p><img src="`+a+'" alt></p><p>AIC/AIV多核结构如下图6所示，AIC/AIV按group划分。一个group内包含1个block和N个subblock（N≥1），其中block表示“主核”，每个subblock表示一个“从核”。</p><p>算子按计算特征可分为三类：Cube算子（矩阵计算）、Vector算子（矢量计算）和Mix算子（同时包含矩阵和矢量计算）。如表4所示，算子类型决定了其所需的核间同步方式和可选的group配置模式。其中Mix算子通过函数执行空间限定符指定AIC与AIV的block/subblock关系；Cube算子和Vector算子为单类核执行，不涉及block/subblock划分。AIV为block且AIC为subblock的配置（即Vector核为主、Cube核为辅的模式）当前不支持。表6总结了核间同步接口及其支持的同步场景。</p><p><strong>图6</strong> block和subblock之间关系（灰色部分表示一个group，即1个block和N个subblock）<a id="fig_block_subblock_relationship"></a></p><p><img src="'+_+'" alt></p><p><strong>表4</strong> group配置</p><table><thead><tr><th>算子类型</th><th>函数执行空间限定符</th><th>核函数（Kernel）类型</th><th>block/subblock</th><th>1：N</th></tr></thead><tbody><tr><td>Cube算子</td><td><code>__cube__</code></td><td><code>KERNEL_TYPE_AIC_ONLY</code></td><td>AIC为block，无subblock</td><td>不涉及</td></tr><tr><td>Vector算子</td><td><code>__vector__</code></td><td><code>KERNEL_TYPE_AIV_ONLY</code></td><td>AIV为block，无subblock</td><td>不涉及</td></tr><tr><td>Mix算子</td><td><code>__mix__(1, 0)</code></td><td><code>KERNEL_TYPE_MIX_AIC_1_0</code></td><td>AIC为block，无subblock</td><td>不涉及</td></tr><tr><td>Mix算子</td><td><code>__mix__(0, 1)</code></td><td><code>KERNEL_TYPE_MIX_AIV_1_0</code></td><td>AIV为block，无subblock</td><td>不涉及</td></tr><tr><td>Mix算子</td><td><code>__mix__(1, 1)</code></td><td><code>KERNEL_TYPE_MIX_AIC_1_1</code></td><td>AIC为block，AIV为subblock</td><td>1：1</td></tr><tr><td>Mix算子</td><td><code>__mix__(1, 2)</code></td><td><code>KERNEL_TYPE_MIX_AIC_1_2</code></td><td>AIC为block，AIV为subblock</td><td>1：2</td></tr></tbody></table><h4 id="核间同步控制模式">核间同步控制模式<a class="header-anchor" href="#核间同步控制模式">​</a></h4><p>图7展示了四种同步控制模式，各模式的功能描述如下。该图基于核函数（Kernel）使用<code>__mix__(1, 2)</code>修饰、逻辑核数<code>numBlocks=4</code>的场景配置。</p><ul><li>模式0：AI Core核间的同步控制。对于AIC全核场景，同步所有的AIC核，直到所有的AIC核都执行到<code>asc_sync_inter_arrive</code>时，<code>asc_sync_inter_wait</code>后续的指令才会执行；对于AIV全核场景，同步所有的AIV核，直到所有的AIV核都执行到<code>asc_sync_inter_arrive</code>时，<code>asc_sync_inter_wait</code>后续的指令才会执行。</li><li>模式1：AI Core内部，AIV核之间的同步控制。如果两个AIV核都运行了<code>asc_sync_subblock_arrive</code>，<code>asc_sync_subblock_wait</code>后续的指令才会执行。</li><li>模式2：AI Core内部，AIC与AIV之间的同步控制。在AIC核执行<code>asc_sync_block_arrive</code>之后，两个AIV上<code>asc_sync_block_wait</code>后续的指令才会继续执行；两个AIV都执行<code>asc_sync_block_arrive</code>后，AIC上<code>asc_sync_block_wait</code>后续的指令才能执行。</li><li>模式4：AI Core内部，AIC与单个AIV之间的同步控制。在单个AIV核执行<code>asc_sync_intra_arrive</code>之后，AIC上<code>asc_sync_intra_wait</code>后续的指令才会继续执行；AIC执行<code>asc_sync_intra_arrive</code>后，单个AIV上<code>asc_sync_intra_wait</code>后续的指令才能执行。AIV0与AIV1可单独触发AIC等待。</li></ul><p><strong>图7</strong> 四种核间同步控制模式示意图<a id="fig_sync_control_mode"></a></p><p><img src="'+o+'" alt></p><h2 id="API列表">API列表<a class="header-anchor" href="#API列表">​</a></h2><h3 id="核内同步">核内同步<a class="header-anchor" href="#核内同步">​</a></h3><p>核内同步接口的分类、适用场景和差异如表5所示。</p><p><strong>表5</strong> 核内同步接口</p><table><thead><tr><th>接口名称</th><th>接口描述</th><th>最细粒度公共头文件</th></tr></thead><tbody><tr><td><a href="intra_core_sync/asc_sync_notify.html">asc_sync_notify</a>/<a href="intra_core_sync/asc_sync_wait.html">asc_sync_wait</a></td><td><strong>多流水同步</strong>：同一核内具有数据依赖的不同类型流水指令之间的同步。<br>需要开发者显式指定一对源流水和目的流水。<code>asc_sync_notify</code>在源流水前序指令的所有读写操作完成后设置标志位；<code>asc_sync_wait</code>阻塞目的流水，直至检测到该标志位，解除阻塞并清除标志位。</td><td><code>c_api/sync/sync.h</code></td></tr><tr><td><a href="intra_core_sync/asc_lock.html">asc_lock</a>/<a href="intra_core_sync/asc_unlock.html">asc_unlock</a></td><td><strong>多流水同步</strong>：同一核内不同流水之间的同步控制。<br>通过<code>mutex_id</code>锁定和释放指定流水。<code>asc_lock</code>根据<code>mutex_id</code>获取Mutex，若Mutex已被锁定，将阻塞指定流水上后续指令的执行；<code>asc_unlock</code>在指定流水的前序指令执行完成后释放对应Mutex。与<code>asc_sync_notify</code>/<code>asc_sync_wait</code>相比，该组合内聚性更强、与其他流水解耦，可简化反向同步逻辑。</td><td><code>c_api/sync/sync.h</code></td></tr><tr><td><a href="intra_core_sync/asc_sync_mte2.html">asc_sync_mte2</a>、<a href="intra_core_sync/asc_sync_mte3.html">asc_sync_mte3</a>、<a href="intra_core_sync/asc_sync_vec.html">asc_sync_vec</a></td><td><strong>多流水同步</strong>：需要同时阻塞多条目的流水，直到指定源流水的前序指令完成。<br><strong>易用性接口</strong>，内部封装了多对<code>asc_sync_notify</code>与<code>asc_sync_wait</code>。<br><code>asc_sync_mte2</code>等价于分别执行<code>PIPE_MTE2</code>-&gt;<code>PIPE_MTE3</code>和<code>PIPE_MTE2</code>-&gt;<code>PIPE_V</code>两组同步。<br><code>asc_sync_mte3</code>等价于分别执行<code>PIPE_MTE3</code>-&gt;<code>PIPE_MTE2</code>和<code>PIPE_MTE3</code>-&gt;<code>PIPE_V</code>两组同步。<br><code>asc_sync_vec</code>等价于分别执行<code>PIPE_V</code>-&gt;<code>PIPE_MTE2</code>、<code>PIPE_V</code>-&gt;<code>PIPE_MTE3</code>和<code>PIPE_V</code>-&gt;<code>PIPE_S</code>三组同步。<br>以上三个接口只能在AIV中调用。</td><td><code>c_api/sync/sync.h</code></td></tr><tr><td><a href="intra_core_sync/asc_sync_pipe.html">asc_sync_pipe</a></td><td><strong>单流水同步</strong>：同一核内具有数据依赖的相同类型流水指令之间的同步。<br>同一流水中虽然指令是顺序执行，但后一条指令开始执行时前一条指令不一定执行结束。<code>asc_sync_pipe</code>保证前序指令中所有数据读写全部完成后，后序指令才开始执行。该接口不支持<code>PIPE_S</code>单流水同步。</td><td><code>c_api/sync/sync.h</code></td></tr><tr><td><a href="intra_core_sync/asc_sync.html">asc_sync</a></td><td><strong>全流水同步</strong>：需要阻塞调用点后所有硬件流水的后序指令，直到调用点之前所有硬件流水的前序指令全部完成。<br>功能与<code>asc_sync_pipe(PIPE_ALL)</code>等价，适用于无法只约束单条流水的场景。</td><td><code>c_api/sync/sync.h</code></td></tr><tr><td><a href="intra_core_sync/asc_sync_data_barrier.html">asc_sync_data_barrier</a></td><td><strong>内存访问屏障</strong>：需要等待此前已发出但尚未完成的内存访问指令全部执行完成。<br>通过<code>arg</code>参数指定屏障作用的内存范围，确保屏障前后的内存访问指令按预期顺序完成。</td><td><code>c_api/sync/sync.h</code></td></tr></tbody></table><h3 id="核间同步">核间同步<a class="header-anchor" href="#核间同步">​</a></h3><p>核间同步接口及其支持的同步场景如表6所示。</p><p><strong>表6</strong> 核间同步接口</p><table><thead><tr><th>接口名称</th><th>接口描述</th><th>最细粒度公共头文件</th></tr></thead><tbody><tr><td><a href="inter_core_sync/asc_sync_inter_arrive.html">asc_sync_inter_arrive</a>/<a href="inter_core_sync/asc_sync_inter_wait.html">asc_sync_inter_wait</a></td><td><strong>同步范围</strong>：组间同步，即不同group之间所有block（所有AIC或所有AIV）之间的同步。<br><strong>对应模式</strong>：模式0（同步等待全部AIC或全部AIV执行结束）<br><code>asc_sync_inter_arrive</code>为生产者，负责发送通知；<code>asc_sync_inter_wait</code>为消费者，负责阻塞等待通知到达。</td><td><code>c_api/sync/sync.h</code></td></tr><tr><td><a href="inter_core_sync/asc_sync_subblock_arrive.html">asc_sync_subblock_arrive</a>/<a href="inter_core_sync/asc_sync_subblock_wait.html">asc_sync_subblock_wait</a></td><td><strong>同步范围</strong>：组内subblock间的同步，即同一group内不同subblock（AIV）之间的同步。<br><strong>对应模式</strong>：模式1（单个AI Core内，全部AIV之间的同步）<br><code>asc_sync_subblock_arrive</code>为生产者，负责发送通知；<code>asc_sync_subblock_wait</code>为消费者，负责阻塞等待通知到达。</td><td><code>c_api/sync/sync.h</code></td></tr><tr><td><a href="inter_core_sync/asc_sync_block_arrive.html">asc_sync_block_arrive</a>/<a href="inter_core_sync/asc_sync_block_wait.html">asc_sync_block_wait</a></td><td><strong>同步范围</strong>：同一group内block（AIC）与所有subblock（AIV）之间的同步。<br><strong>对应模式</strong>：模式2（单个AI Core内，AIC与全部AIV之间的同步）<br><code>asc_sync_block_arrive</code>为生产者，负责发送通知；<code>asc_sync_block_wait</code>为消费者，负责阻塞等待通知到达。</td><td><code>c_api/sync/sync.h</code></td></tr><tr><td><a href="inter_core_sync/asc_sync_intra_arrive.html">asc_sync_intra_arrive</a>/<a href="inter_core_sync/asc_sync_intra_wait.html">asc_sync_intra_wait</a></td><td><strong>同步范围</strong>：同一group内block（AIC）与单个subblock（AIV）之间的同步。<br><strong>对应模式</strong>：模式4（单个AI Core内，AIC核与单个AIV之间同步）<br><code>asc_sync_intra_arrive</code>为生产者，负责发送通知；<code>asc_sync_intra_wait</code>为消费者，负责阻塞等待通知到达。</td><td><code>c_api/sync/sync.h</code></td></tr></tbody></table></article></div>',1)])])}const w=n(P,[["render",I]]);export{m as __pageData,w as default};
